package com.fintrack.khmtomnenh.category.service; import com.fintrack.khmtomnenh.category.dto.CategoryDto; import com.fintrack.khmtomnenh.category.entity.Category; import com.fintrack.khmtomnenh.category.repository.CategoryRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class CategoryService { private final CategoryRepository repo; public List<Category> list(){return repo.findByActiveTrueOrderByNameAsc();} @Transactional public Category create(CategoryDto d){if(repo.existsByNameIgnoreCase(d.name().trim()))throw new IllegalArgumentException("Category name already exists");return repo.save(Category.builder().name(d.name().trim()).description(d.description()).build());} @Transactional public Category update(Long id,CategoryDto d){Category c=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Category not found")); if(repo.existsByNameIgnoreCase(d.name().trim())&&!c.getName().equalsIgnoreCase(d.name().trim()))throw new IllegalArgumentException("Category name already exists"); c.setName(d.name().trim());c.setDescription(d.description());return c;} @Transactional public void delete(Long id){Category c=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Category not found"));c.setActive(false);} }
